"""Phase 12 - hard cases for the test suite.

Hand-curated list of spans (from reading + the analysis scripts). Every span is
validated against the real text of its encounter/field before writing
outputs/eda/hard_cases.jsonl; failures are printed and the file is still
written without them so the suite never contains a non-existent span.
"""
import json

from common import *

recs = {r["encounter_id"]: r for r in load_all()}
